CREATE TABLE model_preparation_artifacts (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    preparation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
    upload_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
    manifest_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(manifest_sha256,'^[a-f0-9]{64}$','c')),
    descriptor JSON NOT NULL CHECK(JSON_TYPE(descriptor)='OBJECT' AND OCTET_LENGTH(CAST(descriptor AS CHAR CHARACTER SET utf8mb4))<=32768),
    report JSON NOT NULL CHECK(JSON_TYPE(report)='OBJECT' AND OCTET_LENGTH(CAST(report AS CHAR CHARACTER SET utf8mb4))<=8388608),
    report_bytes LONGBLOB NOT NULL CHECK(OCTET_LENGTH(report_bytes) BETWEEN 2 AND 8388608),
    storage_path VARCHAR(512) NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    UNIQUE(tenant_id,workspace_id,preparation_id,attempt_id,id),
    FOREIGN KEY(tenant_id,workspace_id,preparation_id,attempt_id) REFERENCES model_preparation_attempts(tenant_id,workspace_id,preparation_id,id),
    FOREIGN KEY(tenant_id,workspace_id,preparation_id,attempt_id,upload_id) REFERENCES model_preparation_uploads(tenant_id,workspace_id,preparation_id,attempt_id,id),
    CHECK(id=upload_id),
    CHECK(storage_path=CONCAT('artifacts/',preparation_id,'/',attempt_id,'/',id)),
    CONSTRAINT model_preparation_artifacts_id_canonical CHECK(REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_artifacts_tenant_id_canonical CHECK(REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_artifacts_workspace_id_canonical CHECK(REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_artifacts_preparation_id_canonical CHECK(REGEXP_LIKE(preparation_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_artifacts_attempt_id_canonical CHECK(REGEXP_LIKE(attempt_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_artifacts_upload_id_canonical CHECK(REGEXP_LIKE(upload_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
